/* Arena scenery for the trainer card only. */
(()=>{
 const scene=document.querySelector('.tp-scene');if(!scene)return;
 let options=[['terminal','Terminal azul'],['viridian','Floresta de Viridian'],['brock','Arena de Brock'],['misty','Arena de Misty'],['mewtwo','Arena de Mewtwo'],['articuno','Arena de Articuno'],['moltres','Arena de Moltres'],['zapdos','Arena de Zapdos']];

 const leaderNames=['Brock','Misty','Lt. Surge','Erika','Koga','Sabrina','Blaine','Giovanni'];
 const entries=options.map(([id,name])=>({id,name,free:id==='terminal'||id==='viridian',metric:id==='brock'||id==='misty'?'badges':'tower',target:id==='brock'?1:id==='misty'?2:id==='articuno'?20:id==='zapdos'?30:id==='moltres'?40:60}));
 ARENA_THEMES.forEach((theme,index)=>{if(index<2||entries.some(e=>e.id===theme.id))return;entries.push({id:theme.id,name:theme.name,theme,metric:index<8?'badges':'tower',target:index<8?index+1:Math.min(60,20+(index-8)*5),leader:leaderNames[index]})});
 function data(){return window.TRAINER_PROFILE_PROGRESS?.()||{badges:0,tower:0}}function amount(o){return o.free?1:Math.min(o.target,data()[o.metric]||0)}function ready(o){return o.free||amount(o)>=o.target}
 function requirement(o){return o.free?'Disponível desde o início da jornada.':o.metric==='badges'?'Conquiste '+o.target+' insígnia'+(o.target>1?'s':'')+' de Kanto'+(o.leader?' · vença '+o.leader:'')+'.':'Alcance o andar '+o.target+' da Torre.'}
 let selected='terminal',applied='terminal';try{const value=localStorage.getItem('profile.arena-background.v1');if(entries.some(o=>o.id===value&&ready(o)))selected=applied=value}catch{}
 const label=document.createElement('label');label.className='tp-arena-background';const caption=document.createElement('span');caption.textContent='Cenário do treinador';const select=document.createElement('select');select.setAttribute('aria-label','Arena de fundo do cartão');label.append(caption,select);scene.after(label);
 const mission=document.createElement('section');mission.className='tp-arena-mission';mission.setAttribute('aria-label','Missão para desbloquear o cenário');label.after(mission);
 function update(){select.replaceChildren();for(const o of entries){const option=document.createElement('option');option.value=o.id;option.textContent=o.name+(ready(o)?'':' · bloqueada');select.append(option)}select.value=selected;const o=entries.find(e=>e.id===selected);mission.replaceChildren();const status=document.createElement('strong'),desc=document.createElement('p');status.textContent=ready(o)?'Cenário equipado':'Prévia · cenário bloqueado';desc.textContent=requirement(o);mission.append(status,desc);if(!o.free){const bar=document.createElement('progress');bar.max=o.target;bar.value=amount(o);bar.setAttribute('aria-label','Missão da arena: '+amount(o)+' de '+o.target);const count=document.createElement('small');count.textContent=amount(o)+' / '+o.target+' · progresso de exemplo';mission.append(bar,count)}const note=document.createElement('small');note.textContent=entries.filter(ready).length+' / '+entries.length+' cenários liberados';mission.append(note)}
 const cache=new Map();
 function renderer(o){if(cache.has(o.id))return cache.get(o.id);let instance=null;const pendingImages=[];if(!o.theme){const factory={viridian:window.createViridianArena,brock:window.createBrockArena,misty:window.createMistyArena,mewtwo:window.createMewtwoArena,articuno:window.createArticunoArena,moltres:window.createMoltresArena,zapdos:window.createZapdosArena}[o.id];if(!factory)return null;const world=document.getElementById('world'),previous=new Set(world.children);const NativeImage=window.Image;function TrackedImage(...args){const image=new NativeImage(...args);pendingImages.push(image);return image}TrackedImage.prototype=NativeImage.prototype;try{window.Image=TrackedImage;instance=factory()}finally{window.Image=NativeImage}for(const child of world.children)if(!previous.has(child))child.style.display='none'}const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=800;const ctx=canvas.getContext('2d');const ready=Promise.all(pendingImages.map(image=>image.complete?Promise.resolve():new Promise(resolve=>{image.addEventListener('load',resolve,{once:true});image.addEventListener('error',resolve,{once:true})})));const item={instance,canvas,ctx,ready};cache.set(o.id,item);return item}
 function paintPreview(r,o){
  const ctx=r.ctx;ctx.clearRect(0,0,1280,800);if(o.theme)paintThemed(ctx,'scene',o.theme);else r.instance.paint(ctx,'scene',true);
  if(!r.field){r.field=document.createElement('canvas');r.field.width=1280;r.field.height=800}const field=r.field.getContext('2d');field.clearRect(0,0,1280,800);if(o.theme)paintThemed(field,'arena',o.theme);else r.instance.paint(field,'arena',true);
  // Apply the same floor tilt as #arenaView; scenery and upright characters remain separate.
  const angle=38*Math.PI/180,project=y=>{const depth=(y-400)*1.02,k=2200/(2200-depth*Math.sin(angle));return {y:400+(6+depth*Math.cos(angle))*k,scale:1.02*k}};
  for(let y=0;y<800;y++){const a=project(y),b=project(y+1);ctx.drawImage(r.field,0,y,1280,1,640-640*a.scale,a.y,1280*a.scale,Math.max(1,b.y-a.y+.4))}
 }
 select.onchange=()=>{selected=select.value;const o=entries.find(e=>e.id===selected);if(ready(o)){applied=selected;try{localStorage.setItem('profile.arena-background.v1',applied)}catch{}}update()};
 addEventListener('trainer-profile-change',()=>{if(!ready(entries.find(o=>o.id===applied))){applied='terminal';try{localStorage.setItem('profile.arena-background.v1',applied)}catch{}}if(!ready(entries.find(o=>o.id===selected)))selected=applied;update()});
 window.TRAINER_CARD_ARENA={async thumbnail(id,canvas){const g=canvas.getContext('2d'),o=entries.find(e=>e.id===id);if(!o)return;g.imageSmoothingEnabled=false;if(id==='terminal'){g.fillStyle='#101f39';g.fillRect(0,0,canvas.width,canvas.height);g.strokeStyle='#285074';g.lineWidth=1;for(let x=0;x<canvas.width;x+=20){g.beginPath();g.moveTo(x,0);g.lineTo(x,canvas.height);g.stroke()}for(let y=0;y<canvas.height;y+=20){g.beginPath();g.moveTo(0,y);g.lineTo(canvas.width,y);g.stroke()}g.fillStyle='#72cefa';g.fillRect(24,24,30,2);g.fillRect(24,24,2,25);g.fillRect(canvas.width-54,canvas.height-24,30,2);return}const r=renderer(o);if(!r)return;canvas.dataset.loading='true';await r.ready;if(!canvas.isConnected)return;delete canvas.dataset.loading;paintPreview(r,o);g.drawImage(r.canvas,0,0,1280,800,0,0,canvas.width,canvas.height)},get entries(){return entries.map(o=>({id:o.id,name:o.name,ready:ready(o),requirement:requirement(o),count:amount(o),target:o.free?1:o.target}))},get selected(){return selected},choose(id){if(!entries.some(o=>o.id===id))return;select.value=id;select.onchange()},active:()=>selected!=='terminal',draw(g){if(selected==='terminal')return false;const o=entries.find(e=>e.id===selected),r=renderer(o);if(!r)return false;paintPreview(r,o);
 // Close framing: trainer and partner stand together inside the field, not over the bench.
 g.drawImage(r.canvas,240,0,800,800,0,0,240,260);g.fillStyle='#08172c15';g.fillRect(0,0,240,260);return true}};update();dispatchEvent(new Event('trainer-card-arena-ready'));
})();
